<section class="admin-welcome"><div><p class="eyebrow">CONSTRUCTEUR DE COURS</p><h1><?= htmlspecialchars($course['title']) ?></h1><p>Organisez le programme comme sur Udemy : sections, leçons, compositions et examen final.</p></div><a class="btn secondary" href="/admin/cours">← Toutes les formations</a></section><div class="builder-layout"><main class="builder-main"><section class="panel builder-add"><h3>+ Ajouter une section</h3><form method="post" action="/admin/cours/programme"><input type="hidden" name="builder_action" value="module"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input name="title" required placeholder="Titre de la section"><input type="number" name="position" value="<?= count($modules)+1 ?>" min="1"><button class="btn primary">Ajouter</button></form></section><?php foreach($modules as $index=>$module): ?><section class="panel builder-section"><header><span>SECTION <?= $index+1 ?></span><h2><?= htmlspecialchars($module['title']) ?></h2></header><div class="builder-items"><?php foreach($module['lessons'] as $lesson): ?><div><b>▶</b><span><strong><?= htmlspecialchars($lesson['title']) ?></strong><small><?= htmlspecialchars($lesson['type']) ?> · <?= (int)$lesson['duration'] ?> min</small></span></div><?php endforeach ?><?php foreach($module['assessments'] as $assessment): ?><div class="quiz-item"><b>?</b><span><strong><?= htmlspecialchars($assessment['title']) ?></strong><small>Composition · seuil <?= $assessment['passing_score'] ?>%</small></span></div><?php endforeach ?></div><details><summary>+ Ajouter une leçon</summary><form method="post" action="/admin/cours/programme" class="builder-form"><input type="hidden" name="builder_action" value="lesson"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input type="hidden" name="module_id" value="<?= $module['id'] ?>"><input name="title" required placeholder="Titre de la leçon"><select name="type"><option value="video">Vidéo</option><option value="text">Article</option><option value="file">Ressource</option></select><input type="number" name="duration" value="10" min="0" placeholder="Minutes"><input type="hidden" name="position" value="<?= count($module['lessons'])+1 ?>"><textarea name="content" placeholder="URL vidéo, texte ou ressource"></textarea><button class="btn primary">Ajouter la leçon</button></form></details><details><summary>+ Ajouter une composition</summary><form method="post" action="/admin/cours/programme" class="builder-form"><input type="hidden" name="builder_action" value="assessment"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input type="hidden" name="module_id" value="<?= $module['id'] ?>"><input name="title" required placeholder="Composition de la section"><input type="hidden" name="type" value="section_quiz"><label>Seuil %<input type="number" name="passing_score" value="70"></label><label>Tentatives<input type="number" name="attempts_allowed" value="3"></label><button class="btn primary">Créer la composition</button></form></details><?php foreach($module['assessments'] as $assessment): ?><details><summary>+ Question pour « <?= htmlspecialchars($assessment['title']) ?> »</summary><form method="post" action="/admin/cours/programme" class="builder-form question-form"><input type="hidden" name="builder_action" value="question"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input type="hidden" name="assessment_id" value="<?= $assessment['id'] ?>"><input class="full" name="question" required placeholder="Énoncé de la question"><input name="option_a" required placeholder="Réponse A"><input name="option_b" required placeholder="Réponse B"><input name="option_c" placeholder="Réponse C"><input name="option_d" placeholder="Réponse D"><input class="full" name="correct_answer" required placeholder="Recopiez exactement la bonne réponse"><button class="btn primary">Ajouter la question</button></form></details><?php endforeach ?></section><?php endforeach ?></main><aside class="panel builder-side"><h3>Examen final</h3><p>Ajoutez l’évaluation qui déclenchera automatiquement le diplôme après réussite.</p><form method="post" action="/admin/cours/programme" class="builder-form"><input type="hidden" name="builder_action" value="assessment"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><input name="title" required placeholder="Examen final"><input type="hidden" name="type" value="final_exam"><label>Seuil de réussite<input type="number" name="passing_score" value="70"></label><label>Tentatives autorisées<input type="number" name="attempts_allowed" value="3"></label><button class="btn primary">Créer l’examen final</button></form></aside></div><style>.builder-layout{display:grid;grid-template-columns:1fr 300px;gap:20px}.builder-main{display:flex;flex-direction:column;gap:15px}.builder-add{padding:18px}.builder-add form,.builder-form{display:grid;grid-template-columns:1fr 100px auto;gap:10px}.builder-add input,.builder-form input,.builder-form select,.builder-form textarea{border:1px solid var(--line);border-radius:7px;padding:10px}.builder-section header{padding:18px;border-bottom:1px solid var(--line)}.builder-section header span{font-size:8px;color:var(--primary)}.builder-section header h2{font-size:16px;margin:4px 0}.builder-items>div{display:flex;gap:12px;padding:13px 20px;border-bottom:1px solid var(--line)}.builder-items span{display:flex;flex-direction:column}.builder-items small{color:var(--muted)}.quiz-item{background:#faf9ff}.builder-section details{padding:13px 20px;border-top:1px solid var(--line)}.builder-section summary{cursor:pointer;color:var(--primary);font-weight:700}.builder-form{grid-template-columns:repeat(2,1fr);margin-top:14px}.builder-form textarea,.builder-form button,.builder-form .full{grid-column:1/-1}.builder-side{padding:20px;align-self:start;position:sticky;top:95px}.builder-side .builder-form{grid-template-columns:1fr}.builder-side .builder-form>*{grid-column:1}@media(max-width:800px){.builder-layout{grid-template-columns:1fr}.builder-side{position:static}.builder-add form,.builder-form{grid-template-columns:1fr}.builder-form>*{grid-column:1!important}}</style>
